class Solution:
    def maxUpgradableServers(self, count: list[int], upgrade: list[int], sell: list[int], money: list[int]) -> list[int]:
        ans = []
        for c, u, s, m in zip(count, upgrade, sell, money):
            k = (m + c * s) // (u + s)
            ans.append(min(c, k))
        return ans

class Solution {
public:
    vector<int> maxUpgradableServers(vector<int>& count, vector<int>& upgrade, vector<int>& sell, vector<int>& money) {
        int n = count.size();
        vector<int> ans(n);
        for (int i = 0; i < n; ++i) {
            long long total = 1LL * money[i] + 1LL * count[i] * sell[i];
            long long k = total / (upgrade[i] + sell[i]);
            ans[i] = min((long long)count[i], k);
        }
        return ans;
    }
};

class Solution {
    public int[] maxUpgradableServers(int[] count, int[] upgrade, int[] sell, int[] money) {
        int n = count.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            long total = (long) money[i] + (long) count[i] * sell[i];
            long k = total / (upgrade[i] + sell[i]);
            ans[i] = (int) Math.min((long) count[i], k);
        }
        return ans;
    }
}

var maxUpgradableServers = function(count, upgrade, sell, money) {
    const n = count.length;
    const ans = new Array(n);
    for (let i = 0; i < n; ++i) {
        const total = BigInt(money[i]) + BigInt(count[i]) * BigInt(sell[i]);
        const k = total / (BigInt(upgrade[i]) + BigInt(sell[i]));
        const c = BigInt(count[i]);
        ans[i] = Number(k < c ? k : c);
    }
    return ans;
};
